curl -s -X POST https://slack.com/api/users.list -H "Authorization: Bearer <TOKEN>" -d "token=<TOKEN>" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for user in data['members']:
        print(f\"{user['id']}: {user['profile']['real_name']}\")
else:
    print(data)
"

curl -s -X POST https://slack.com/api/conversations.list -H "Authorization: Bearer <TOKEN>" -d "token=<TOKEN>&types=private_channel&limit=100" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for ch in data['channels']:
        print(f\"{ch['id']}: name={ch['name']}, purpose={ch.get('purpose', {}).get('value', 'N/A')}\")
else:
    print(data)
"

curl -s -X POST https://slack.com/api/conversations.list -H "Authorization: Bearer <TOKEN>" -d "token=<TOKEN>&types=public_channel,private_channel,mpim&limit=100" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for ch in data['channels']:
        purpose = ch.get('purpose', {}).get('value', 'N/A')
        print(f\"id={ch['id']}, name={ch['name']}, is_private={ch.get('is_private', False)}, purpose={purpose}\")
else:
    print(data)
"
